<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galeri | SIAP-Kukar</title><style>body{margin:0;background:#f4f7f3;color:#17201d;font-family:Inter,system-ui,sans-serif}.wrap{max-width:1200px;margin:auto;padding:35px 24px}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}h1{font-size:36px;letter-spacing:-.06em}.filters{display:flex;gap:8px}.filters a,.back{padding:10px 14px;border:1px solid #e5e9e6;border-radius:10px;background:#fff;text-decoration:none;color:#17201d;font-size:12px;font-weight:750}.filters a.active{background:#17201d;color:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{overflow:hidden;border:1px solid #e5e9e6;border-radius:16px;background:#fff;box-shadow:0 12px 30px #17201d0c;cursor:pointer}.card img,.card .video{width:100%;height:220px;object-fit:cover;background:#202923}.info{padding:15px}.info strong{display:block;margin-bottom:6px}.info small{color:#68736f;line-height:1.5}@media(max-width:700px){.head{align-items:start;gap:15px;flex-direction:column}.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="head"><div><a class="back" href="{{ route('home') }}">← Beranda</a><h1>Galeri Asrama</h1><p>Fasilitas, kamar, dan kegiatan Asrama Putri Junjung Buyah.</p></div><nav class="filters"><a class="{{ !$kategori ? 'active' : '' }}" href="{{ route('gallery.public') }}">Semua</a>@foreach(['fasilitas' => 'Fasilitas','kamar' => 'Kamar','kegiatan' => 'Kegiatan'] as $key => $label)<a class="{{ $kategori === $key ? 'active' : '' }}" href="{{ route('gallery.public', ['kategori' => $key]) }}">{{ $label }}</a>@endforeach</nav></div><div class="grid">@forelse($galleries as $gallery)<article class="card" data-src="{{ $gallery->jenis === 'foto' ? asset('storage/'.$gallery->file_path) : $gallery->file_path }}" data-type="{{ $gallery->jenis }}" onclick="openMedia(this)">@if($gallery->jenis === 'foto')<img src="{{ asset('storage/'.$gallery->file_path) }}" alt="{{ $gallery->judul }}">@else<div class="video">▶ Video</div>@endif<div class="info"><strong>{{ $gallery->judul }}</strong><small>{{ $gallery->keterangan ?: 'Tidak ada keterangan.' }}</small></div></article>@empty<p>Belum ada media.</p>@endforelse</div></main><script>function openMedia(card){const win=window.open('','_blank','width=900,height=700');win.document.write(card.dataset.type==='foto'?`<img src="${card.dataset.src}" style="max-width:100%;max-height:100vh;display:block;margin:auto">`:`<iframe src="${card.dataset.src}" style="width:100%;height:100vh;border:0" allowfullscreen></iframe>`);}</script></body></html>
